// Languages with published pages, so a footer link only points at a
// directory that exists. Anything else falls back to the English page.
export const AVAILABLE = new Set(["ar", "bn", "de", "en", "es", "fr", "hi", "id", "ja", "mr", "pt", "ru", "sv", "te", "ur", "zh"]);

export function strings(lang) {
  return EMAIL_STRINGS[lang] || EMAIL_STRINGS.en;
}
